export fn palindrome_with_stack(v:[*c]const i64,n:usize)i64{if(v==null or n<1 or n>129 or v[0]<0 or v[0]>128 or n!=@as(usize,@intCast(v[0]))+1)return -1;const len:usize=@intCast(v[0]);var stack=[_]u8{0}**128;for(0..len)|i|{const x=v[i+1];if(x<0 or x>127)return -1;var c:u8=@intCast(x);if(c>=65 and c<=90)c+=32;stack[i]=c;}for(0..len)|i|{if(stack[i]!=stack[len-1-i])return 0;}return 1;}
